# opencode
# Bash completion for opencode, generated by `opencode --completions bash`.
#
# The generated script is ~40 KB and the generator costs roughly 100 ms, so it
# is cached under XDG_CACHE_HOME and regenerated only when the cache is missing
# or older than the opencode binary. The cache holds the same script the
# generator would have produced, so this is equivalent to the upstream advice
# to append `opencode --completions bash` to a startup file.
#
# Caching is best effort. A read-only cache directory simply means completion
# is skipped; it never fails shell startup.

command -v opencode >/dev/null 2>&1 || return 0

_opencode_cache_dir=${XDG_CACHE_HOME:-$HOME/.cache}/opencode
_opencode_cache=$_opencode_cache_dir/completions.bash

if [ -r "$_opencode_cache" ] && [ "$_opencode_cache" -nt "$(command -v opencode)" ]; then
    # shellcheck source=/dev/null
    . "$_opencode_cache"
elif _opencode_script=$(opencode --completions bash 2>/dev/null) && [ -n "$_opencode_script" ]; then
    if mkdir -p -- "$_opencode_cache_dir" 2>/dev/null; then
        printf '%s\n' "$_opencode_script" > "$_opencode_cache" 2>/dev/null || :
    fi
    eval "$_opencode_script"
fi

unset _opencode_cache_dir _opencode_cache _opencode_script
